    var dec = function (v, c) { return v === null || v === undefined || v === '' ? '' : (typeof v === 'number' ? v.toFixed(c).replace('.', ',') : String(v)); };
    var esc = function (v) { var s = v === null || v === undefined ? '' : String(v); return /[";\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
    var linhas = [cab.join(';')];
    rs.forEach(function (r) {
