/* Mapa de fiscais. Folha escrita à mão. Mobile-first. */
*,*::before,*::after{box-sizing:border-box}
:root{
  --paper:#f8f5ec;--card:#fffdf8;--ink:#151812;--ink2:#2a2f27;--muted:#535b54;--line:#d5d2c6;
  --alta:#7a3500;--media:#b8700f;--media-txt:#8a5410;--baixa:#6f7a86;--baixa-txt:#505a66;
  --log3:#5b2a86;--log2:#0f5d6e;--log1:#4f8fa0;--log0:#9cb9c2;--log0-txt:#3f5f68;
  --risco:#5b2a86;--azul:#0d2238;--azul2:#1f5f9e;--amarelo:#ffcc29;--verde:#0b7a3b;--verde-esc:#095f2e;
  --flavio:#1f5f9e;--lula:#c8412f;--outros:#b9b5a6;
  --sans:"IBM Plex Sans Condensed","Arial Narrow",Arial,sans-serif;--mono:"IBM Plex Mono",ui-monospace,monospace;--display:Georgia,serif;
}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--sans);font-size:17px;line-height:1.5;overflow-x:hidden}
a{color:var(--azul2)}
:focus-visible{outline:3px solid var(--ink);outline-offset:2px;box-shadow:0 0 0 5px #fff}
.skip{position:absolute;left:-9999px}
.skip:focus{left:8px;top:8px;background:var(--ink);color:#fff;padding:8px 12px;z-index:2000}
[hidden]{display:none!important}
b,strong{font-weight:700}

/* ---------- topo ---------- */
.topo{background:var(--ink);color:#f4f2ea;padding:10px 16px}
.topo-in{display:flex;flex-wrap:wrap;align-items:center;gap:8px 18px}
.marca{display:inline-flex;align-items:center;gap:8px;color:#c9cfc6;text-decoration:none;font-family:var(--mono);font-size:.72rem;letter-spacing:.12em;text-transform:uppercase;min-height:44px}
.marca img{border-radius:4px}
.topo-t{flex:1 1 320px;min-width:0}
.topo h1{margin:0;font-family:var(--display);font-size:1.55rem;line-height:1.1}
.topo p{margin:2px 0 0;font-size:.95rem;color:#d7dbd3}
.topo p a{color:var(--amarelo)}
.btn-fiscal{display:inline-flex;align-items:center;min-height:44px;padding:8px 14px;border-radius:8px;background:var(--amarelo);color:var(--ink);font-weight:700;text-decoration:none;border:2px solid var(--amarelo)}
.btn-fiscal:hover{background:transparent;color:var(--amarelo)}

/* ---------- intro: o que é o mapa, em três números ---------- */
.intro{background:#e7eef1;border-bottom:1px solid var(--line);padding:16px}
.intro-in{display:grid;gap:14px;max-width:1400px;margin:0 auto}
.kicker{font:11px var(--mono);text-transform:uppercase;letter-spacing:.12em;color:var(--muted);margin:0 0 6px}
.intro h2{font:500 1.5rem/1.15 var(--display);margin:0 0 8px;max-width:28ch}
.intro p{margin:0;max-width:70ch}
.intro-num{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin:0}
.intro-num>div{background:#fff;border:1px solid var(--line);border-radius:10px;padding:10px 12px;display:flex;flex-direction:column}
.intro-num dd{margin:0;font:700 1.6rem/1 var(--display);order:0}
.intro-num dt{font-size:.86rem;color:var(--muted);margin-top:4px;line-height:1.3}
.como-ler summary{min-height:44px;display:flex;align-items:center;cursor:pointer;font-weight:600}
.legenda{list-style:none;margin:6px 0 0;padding:0;display:grid;gap:4px 16px;grid-template-columns:repeat(auto-fit,minmax(260px,1fr))}
.legenda li{display:flex;align-items:flex-start;gap:8px;font-size:.95rem}
.legenda .pt{margin-top:5px}
.legenda small{display:block;color:var(--muted)}
#sem-ocorrencia,#cobertura-logs{font-size:.9rem;color:var(--muted);margin:8px 0 0}

/* ---------- aplicativo ---------- */
.app{display:grid;grid-template-columns:1fr;min-height:0}
.filtros-toggle{display:flex;align-items:center;justify-content:space-between;width:100%;min-height:48px;border:0;border-bottom:1px solid var(--line);background:var(--card);color:var(--ink);font:inherit;font-weight:700;padding:8px 16px;cursor:pointer}
.filtros-toggle::after{content:"▾";transition:transform .15s}
.filtros-toggle[aria-expanded=true]::after{transform:rotate(180deg)}
.controles{padding:12px 16px;display:grid;gap:12px;align-content:start;background:var(--card);border-bottom:1px solid var(--line)}
body:not(.filtros-abertos) .controles{display:none}
.bloco{border:1px solid var(--line);border-radius:10px;padding:10px 12px;margin:0;background:#fff;min-width:0}
.bloco h2{font-family:var(--display);font-size:1.1rem;font-weight:500;margin:0 0 6px}
.rot{display:block;font-family:var(--mono);font-size:.68rem;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin:8px 0 4px}
.rot-inline{display:inline;margin:0 6px 0 0}
input[type=text],input[type=search],select{width:100%;min-height:44px;border:2px solid #b9b5a6;border-radius:8px;background:#fff;color:var(--ink);font:inherit;font-size:1rem;padding:6px 10px}
input:focus,select:focus{border-color:var(--azul2);outline:3px solid rgb(31 95 158 / 25%)}
select:disabled{background:#efece2;color:var(--muted)}
#q-cep,#f-zona{font-family:var(--mono);letter-spacing:.05em}
.duas-col{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.acoes{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}
.btn{min-height:44px;border-radius:8px;border:2px solid transparent;font:inherit;font-weight:700;padding:8px 16px;cursor:pointer}
.btn-prim{background:var(--verde);color:#fff;flex:1}
.btn-prim:hover{background:var(--verde-esc)}
.btn-sec{background:#fff;color:var(--azul);border-color:var(--azul)}
.btn-sec:hover{background:var(--azul);color:#fff}
.btn-geo{width:100%;margin-top:8px}
.btn:disabled{opacity:.6;cursor:wait}
.ajuda{font-size:.88rem;color:var(--muted);margin:8px 0 0}

/* níveis: duas famílias de cor, histórico (quente) e log (frio) */
.niveis-grupo+.niveis-grupo{margin-top:8px}
.niveis-grupo .rot{margin-top:4px}
.nv{display:flex;align-items:center;gap:10px;min-height:44px;cursor:pointer;font-weight:600;padding:0 2px}
.nv input{width:22px;height:22px;margin:0;accent-color:var(--ink);flex:none}
.nv-t{display:flex;flex:1;align-items:baseline;justify-content:space-between;gap:8px}
.nv-t small{font-family:var(--mono);font-weight:400;color:var(--muted)}
#niveis.inativo{opacity:.45}
.pt{width:14px;height:14px;border-radius:50%;flex:none;border:2px solid #fff;box-shadow:0 0 0 1px var(--ink)}
.nv-alta .pt,.pt-alta{background:var(--alta)}.nv-media .pt,.pt-media{background:var(--media)}.nv-baixa .pt,.pt-baixa{background:var(--baixa)}
.nv-log3 .pt,.pt-log3{background:var(--log3)}.nv-log2 .pt,.pt-log2{background:var(--log2)}.nv-log1 .pt,.pt-log1{background:var(--log1)}.nv-log0 .pt,.pt-log0{background:var(--log0)}
.criterio-ativo{padding:10px 12px;margin-top:10px;background:#edf4f7;border-left:3px solid var(--azul2);font-size:.92rem;border-radius:0 8px 8px 0}
.criterio-ativo p{margin:6px 0}
.raios{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}
.raios button{min-height:44px;border:2px solid var(--line);border-radius:8px;background:#fff;color:var(--ink);font:inherit;font-weight:700;cursor:pointer}
.raios button[aria-checked=true]{background:var(--ink);border-color:var(--ink);color:#fff}
.modo{display:grid;grid-template-columns:1fr 1fr;gap:6px}
.btn-modo{min-height:44px;border:2px solid var(--azul);border-radius:8px;background:#fff;color:var(--azul);font:inherit;font-weight:700;cursor:pointer}
.btn-modo[aria-pressed=true]{background:var(--azul);color:#fff}
.recorte-ativo{font-size:.95rem;font-weight:600;margin:0;border-top:2px solid var(--azul2);padding-top:10px}
.status{margin:0;font-size:.95rem;background:#fff8dc;border-left:4px solid var(--amarelo);padding:8px 10px;border-radius:0 8px 8px 0}
.status.erro{background:#fbecea;border-left-color:#a8321f}

/* ---------- mapa ---------- */
.palco{min-width:0;position:relative}
.mapa{height:68vh;min-height:420px;background:#e8e4d8}
.aviso{padding:20px}
.pino{border-radius:50%;border:2px solid #fff;box-shadow:0 0 0 1.5px var(--ink),0 1px 4px rgb(0 0 0 / 35%)}
.pino-varias{transform:scale(1.25)}
.pino-alta{background:var(--alta)}.pino-media{background:var(--media)}.pino-baixa{background:var(--baixa)}
.pino-log3{background:var(--log3)}.pino-log2{background:var(--log2)}.pino-log1{background:var(--log1)}.pino-log0{background:var(--log0)}
.grupo{border-radius:50%;display:flex;align-items:center;justify-content:center;color:#fff;font:700 13px/1 var(--sans);border:3px solid rgb(255 255 255 / 85%);box-shadow:0 0 0 1.5px var(--ink)}
.grupo span{padding:0 2px}
.grupo-alta{background:var(--alta)}.grupo-media{background:#9a5d10}.grupo-baixa{background:#505a66}
.grupo-log3{background:var(--log3)}.grupo-log2{background:var(--log2)}.grupo-log1{background:#3f7f90}.grupo-log0{background:#5f8590}
.alvo{border-radius:50%;background:var(--amarelo);border:3px solid var(--ink);box-shadow:0 0 0 3px #fff}
.leaflet-container{font-family:var(--sans)}
.leaflet-control-zoom a{width:40px!important;height:40px!important;line-height:40px!important;font-size:22px!important}
/* números das seções escritos no mapa, só com zoom de quarteirão */
.rotulo-secoes{background:#fff;border:1px solid var(--ink);border-radius:6px;padding:2px 7px;font:600 12px/1.2 var(--sans);color:var(--ink);box-shadow:0 1px 3px rgb(0 0 0 / 25%);white-space:nowrap}
.rotulo-secoes::before{display:none}
.mapa:not(.com-rotulos) .rotulo-secoes{display:none}

/* ---------- ficha do prédio ---------- */
.leaflet-popup-content{margin:12px 14px;font-size:.95rem;line-height:1.45}
.popup-ficha .leaflet-popup-content-wrapper{border-radius:12px}
.ficha h3{font-family:var(--display);font-size:1.15rem;line-height:1.2;margin:4px 0 4px}
.ficha p{margin:4px 0}
.ficha-end,.ficha-meta{color:var(--muted);font-size:.9rem}
.ficha-secoes{list-style:none;margin:8px 0;padding:0;display:grid;gap:8px;max-height:300px;overflow-y:auto}
.sec{border:1px solid var(--line);border-radius:8px;padding:8px 10px;background:#fff}
.sec-atual{border-color:var(--ink);box-shadow:0 0 0 2px var(--amarelo)}
.sec-cab{display:flex;flex-wrap:wrap;align-items:center;gap:6px;font-size:1rem}
.sec-res p{margin:4px 0 2px}
.sec-res.sem{color:var(--muted);font-style:italic}
.sec-placar small{color:var(--muted);font-weight:400}
.tf{color:var(--flavio)}.tl{color:var(--lula)}
.placar{display:flex;height:8px;border-radius:4px;overflow:hidden;background:var(--outros);margin:4px 0 6px}
.placar span{display:block;height:100%}
.p-f{background:var(--flavio)}.p-l{background:var(--lula)}.p-o{background:var(--outros)}
.sec-motivos{margin:4px 0;padding-left:18px;font-size:.92rem}
.sec-motivos li+li{margin-top:2px}
.sec-expl,.sec-pol{color:var(--muted);font-size:.88rem}
.sec-pol:empty{display:none}
.sec-links{font-size:.9rem}
.sec-outras{display:flex;flex-wrap:wrap;gap:4px}
.sec-outras a{display:inline-block;min-width:36px;text-align:center;border:1px solid var(--line);border-radius:6px;padding:2px 6px;text-decoration:none;font-family:var(--mono);font-size:.82rem}
.ficha-extra details summary{cursor:pointer;color:var(--azul2);font-size:.9rem}
.ficha-risco{border-left:3px solid var(--risco);padding-left:8px;font-size:.9rem}
.ficha-conf{background:var(--paper);padding:6px 10px;border-radius:6px;font-size:.9rem}
.ficha-conf ul{margin:4px 0 0;padding-left:18px}
.ficha-links a{font-weight:700}
.chip{display:inline-block;font-family:var(--mono);font-size:.66rem;letter-spacing:.06em;text-transform:uppercase;padding:2px 8px;border-radius:999px;color:#fff;white-space:nowrap;line-height:1.5}
